def serialize(root):
    result = []
    def dfs(node):
        if node is None:
            result.append('null')                        # explicit marker for a missing child
            return
        result.append(str(node.val))
        dfs(node.left)
        dfs(node.right)
    dfs(root)
    return ','.join(result)

def deserialize(data):
    values = iter(data.split(','))
    def build():
        token = next(values)
        if token == 'null':
            return None
        node = TreeNode(int(token))
        node.left = build()                                  # consume tokens in the SAME preorder sequence
        node.right = build()
        return node
    return build()

