public class Main {
    public static String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        dfs(root, sb);
        return sb.toString();
    }

    static void dfs(TreeNode node, StringBuilder sb) {
        if (node == null) { sb.append("null,"); return; }        // explicit marker for a missing child
        sb.append(node.val).append(",");
        dfs(node.left, sb);
        dfs(node.right, sb);
    }

    static int idx;
    public static TreeNode deserialize(String data) {
        String[] tokens = data.split(",");
        idx = 0;
        return build(tokens);
    }

    static TreeNode build(String[] tokens) {
        String token = tokens[idx++];
        if (token.equals("null")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(token));
        node.left = build(tokens);                                  // consume tokens in the SAME preorder sequence
        node.right = build(tokens);
        return node;
    }
}

